@media (max-width: 900px) { .foot .cols { grid-template-columns: 1fr; gap: 40px; } }
.mbar { display: none; }
@media (max-width: 760px) {
  .top .wrap { min-height: 64px; flex-wrap: wrap; row-gap: 0; padding-top: 8px; padding-bottom: 8px; }
  .logo { font-size: 24px; }
